import numpy as np

def speculative_sample_token(p, q, rng=None):
    rng = rng or np.random.default_rng()
    p, q = np.asarray(p, dtype=float), np.asarray(q, dtype=float)
    if p.ndim != 1 or q.shape != p.shape or np.any(p < 0) or np.any(q < 0):
        raise ValueError("p and q must be same-shaped nonnegative vectors")
    if not np.isclose(p.sum(), 1) or not np.isclose(q.sum(), 1):
        raise ValueError("p and q must each sum to 1")
    proposal = rng.choice(len(q), p=q)
    if q[proposal] > 0 and rng.random() < min(1.0, p[proposal] / q[proposal]):
        return proposal
    residual = np.maximum(p - q, 0)
    if residual.sum() <= 0:
        return rng.choice(len(p), p=p)
    residual /= residual.sum()
    return rng.choice(len(p), p=residual)
